<script>const gtStore=@json(route('goal-types-store')),gtUpdate=@json(route('goal-types-update','__ID__'));function editGT(x){let d=JSON.parse(atob(x)),f=gtForm;f.action=gtUpdate.replace('__ID__',d.id);gtMethod.innerHTML='<input type="hidden" name="_method" value="PUT">';f.elements.name.value=d.name;f.elements.description.value=d.description||'';f.elements.status.value=d.status?1:0;gtTitle.textContent='Edit Goal Type';gtSave.textContent='Update Goal Type';gtCancel.style.display='block';window.scrollTo({top:0,behavior:'smooth'})}function resetGT(){let f=gtForm;f.reset();f.action=gtStore;gtMethod.innerHTML='';gtTitle.textContent='Add New Goal Type';gtSave.textContent='Add Goal Type';gtCancel.style.display='none';f.querySelectorAll('.gt-error').forEach(x=>x.remove());f.querySelectorAll('.gt-invalid').forEach(x=>x.classList.remove('gt-invalid'))}function moreGT(b){let d=b.parentElement.querySelector('.gt-description'),open=b.dataset.open==='1';d.textContent=atob(open?b.dataset.short:b.dataset.full);b.dataset.open=open?'0':'1';b.textContent=open?'⌄ Show more':'⌃ Show less'}document.addEventListener('DOMContentLoaded',()=>{let f=gtForm,rules={name:e=>!e.value.trim()?'Goal Type Name is required':e.value.trim().length<2?'Goal Type Name must be at least 2 characters':'',status:e=>e.value===''?'Status is required':''};function valid(e){let m=rules[e.name](e),x=e.parentElement.querySelector('.gt-error');if(!x){x=document.createElement('div');x.className='gt-error';e.after(x)}e.classList.toggle('gt-invalid',!!m);x.textContent=m;return !m}Object.keys(rules).forEach(k=>['input','change','blur'].forEach(v=>f.elements[k].addEventListener(v,()=>valid(f.elements[k]))));f.onsubmit=e=>{let first;Object.keys(rules).forEach(k=>{if(!valid(f.elements[k])&&!first)first=f.elements[k]});if(first){e.preventDefault();first.focus()}};document.querySelectorAll('.gt-delete').forEach(x=>x.onsubmit=e=>{if(x.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete goal type?',text:'This action cannot be undone.',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){x.dataset.ok=1;x.submit()}})})})</script>@endsection
